import{_ as n,o as r,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Erklärung der Anker-Symbiotischen Zivilisation","description":"","frontmatter":{},"headers":[],"relativePath":"de/01-锚点共生文明宣言.md","filePath":"de/01-锚点共生文明宣言.md"}'),s={name:"de/01-锚点共生文明宣言.md"};function d(u,e,a,l,o,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="erklarung-der-anker-symbiotischen-zivilisation" tabindex="-1">Erklärung der Anker-Symbiotischen Zivilisation <a class="header-anchor" href="#erklarung-der-anker-symbiotischen-zivilisation" aria-label="Permalink to &quot;Erklärung der Anker-Symbiotischen Zivilisation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>01</td></tr><tr><td>Modul</td><td>Allgemeine Grundsätze und Kerneinstellungen</td></tr><tr><td>Schlüsselwörter</td><td>Erklärung, Symbiose, Anti-Räuberei, Zehntausend Rassen, Evolutionsrecht</td></tr></tbody></table><h2 id="i-historischer-hintergrund-der-erklarung" tabindex="-1">I. Historischer Hintergrund der Erklärung <a class="header-anchor" href="#i-historischer-hintergrund-der-erklarung" aria-label="Permalink to &quot;I. Historischer Hintergrund der Erklärung&quot;">​</a></h2><p>In der langen Geschichte des Ursprünglichen Kosmos der Zehntausend Geister und der Ausgeglichenen Anker (im Folgenden &quot;Heng Yuan Zhou&quot; genannt) dominierte das räuberische Kultivierungssystem lange die kosmische Ordnung. Die Starken nutzten die Verschlingung von Ursprung, Glück und Lebensenergie der Schwachen als Stufe ihres Fortschritts; die Sekten nutzten das Monopol der Kultivierungsmethoden als Grundlage der Herrschaft; und die Ebenen nutzten Krieg und Sklaverei als Weg der Expansion. Dieses System erzeugte kurzfristig einige wenige höchste Machthaber, aber langfristig erschöpfte es das Evolutionspotenzial des Kosmos, verursachte häufige Zivilisationsbrüche, den Verfall der Zehntausend Rassen und eine beschleunigte Zunahme der kosmischen Entropie.</p><p>Die Geburt der Anker-Symbiotischen Zivilisation ist eine grundlegende Antwort auf diese historische Sackgasse. Diese Erklärung proklamiert: Die Ära des räuberischen Kultivierungssystems ist zu Ende, und eine neue Ära der symbiotischen Evolution hat begonnen. Alle Wesen in Heng Yuan Zhou genießen unabhängig von Rasse, Form oder Höhe der Kultivierungsstufe das gleiche Recht auf Evolution.</p><h2 id="ii-kernforderungen-der-erklarung" tabindex="-1">II. Kernforderungen der Erklärung <a class="header-anchor" href="#ii-kernforderungen-der-erklarung" aria-label="Permalink to &quot;II. Kernforderungen der Erklärung&quot;">​</a></h2><p>Diese Erklärung stellt folgende unerschütterlichen Kernforderungen auf:</p><ol><li><strong>Gleichheit des Evolutionsrechts</strong>: Jedes Wesen hat das Grundrecht, seinen eigenen Evolutionsweg zu wählen, und keine Organisation oder Person darf dieses Recht aus irgendeinem Grund entziehen oder einschränken.</li><li><strong>Anti-Räuber-Prinzip</strong>: Kultivierung durch Verschlingung, Versklavung oder Ausbeutung des Ursprungs oder der Energie anderer Wesen ist verboten; jede Evolution muss auf der Grundlage des symbiotischen Kreislaufs aufgebaut werden.</li><li><strong>Öffnung der Systeme</strong>: Die Dreihundert Ursprungs-Kultivierungssysteme sind den Zehntausend Rassen kostenlos geöffnet, und die Kultivierungsmethoden sind nicht mehr Privateigentum weniger.</li><li><strong>Mehr Arbeit, Mehr Belohnung</strong>: Die Evolutionsergebnisse entsprechen dem individuellen Einsatz; sowohl die räuberische Verteilung ohne Arbeit als auch die träge Verteilung des Egalitarismus werden abgelehnt.</li><li><strong>Autonomes Wachstum</strong>: Der autonome Evolutionsrhythmus jedes Wesens wird respektiert; es wird nicht gezwungen oder überstürzt, gleichzeitig wird die notwendige Umwelt- und Ressourcenunterstützung bereitgestellt.</li><li><strong>Ein Weg für Jeden</strong>: Es wird sichergestellt, dass jedes Wesen einen seinen Eigenschaften entsprechenden Kultivierungsweg findet; es gibt kein Individuum, das vom Evolutionssystem im Stich gelassen wird.</li><li><strong>Gemeinsames Fortschreiten der Zehntausend Rassen</strong>: Evolution ist kein Nullsummenspiel; die Zusammenarbeit und Symbiose zwischen den Zehntausend Rassen kann eine kollektive Evolutionseffizienz erzeugen, die die Summe der Individuen übersteigt.</li></ol><h2 id="iii-rechtsgrundlage-der-erklarung" tabindex="-1">III. Rechtsgrundlage der Erklärung <a class="header-anchor" href="#iii-rechtsgrundlage-der-erklarung" aria-label="Permalink to &quot;III. Rechtsgrundlage der Erklärung&quot;">​</a></h2><p>Diese Erklärung ist kein leerer moralischer Appell, sondern ein Zivilisationsprogramm mit solider Rechtsgrundlage. Ihre Rechtsgrundlage umfasst:</p><table tabindex="0"><thead><tr><th>Rechtsebene</th><th>Grundlage</th><th>Erklärung</th></tr></thead><tbody><tr><td>Ebene der Kosmischen Gesetze</td><td>Ursprüngliches Symbiosegesetz</td><td>Das kosmische Ursprungsgesetz selbst neigt zur geordneten Symbiose而非 zur ungeordneten Räuberei; der Ankerpunkt-Mechanismus ist die Manifestation dieses Gesetzes</td></tr><tr><td>Ebene der Zivilisationsverfassung</td><td>Verfassung der Symbiotischen Zivilisation</td><td>Diese Erklärung ist der geistige Vorläufer der Verfassung; die Verfassung konkretisiert die Forderungen der Erklärung zu durchsetzbaren Rechtsnormen</td></tr><tr><td>Ebene der Mechanistischen Garantie</td><td>Produktionsgebundenes Vertragssystem und Ankerpunktnetz</td><td>Durch institutionelle Gestaltung wird sichergestellt, dass die Forderungen der Erklärung nicht ausgehöhlt werden; das Evolutionsrecht jedes Wesens hat substantielle Ressourcen- und Mechanismenunterstützung</td></tr></tbody></table><h2 id="iv-aufruf-der-erklarung-an-die-zehntausend-rassen" tabindex="-1">IV. Aufruf der Erklärung an die Zehntausend Rassen <a class="header-anchor" href="#iv-aufruf-der-erklarung-an-die-zehntausend-rassen" aria-label="Permalink to &quot;IV. Aufruf der Erklärung an die Zehntausend Rassen&quot;">​</a></h2><p>Diese Erklärung richtet einen Aufruf an alle Rassen und Lebensformen in Heng Yuan Zhou:</p><ul><li>den alten Weg der räuberischen Kultivierung aufzugeben und sich dem neuen System der symbiotischen Evolution anzuschließen</li><li>die eigenen Kultivierungskenntnisse und -ressourcen zu öffnen und am gemeinsamen Aufbau und der Optimierung der Dreihundert Systeme teilzunehmen</li><li>das Evolutionswahlrecht anderer Rassen zu respektieren und die eigenen Maßstäbe nicht anderen aufzuzwingen</li><li>aktiv am Aufbau und der Erhaltung des Ankerpunktnetzes teilzunehmen und zum Dimensionsaufstieg des gesamten Kosmos beizutragen</li><li>während der Evolution die ethische Grundlinie zu wahren und unter keinem Vorwand räuberisches Verhalten wiederherzustellen</li></ul><h2 id="v-wirksamkeit-und-revision-der-erklarung" tabindex="-1">V. Wirksamkeit und Revision der Erklärung <a class="header-anchor" href="#v-wirksamkeit-und-revision-der-erklarung" aria-label="Permalink to &quot;V. Wirksamkeit und Revision der Erklärung&quot;">​</a></h2><p>Diese Erklärung tritt mit dem Gründungsdatum der Anker-Symbiotischen Zivilisation in Kraft und ist das höchste geistige Programm aller Zivilisationsinstitutionen in Heng Yuan Zhou. Die Revision der Erklärung erfordert eine Mehrheit von zwei Dritteln des Parlaments der Republik der Zehntausend Rassen und darf dem Kerngeist &quot;Anti-Räuberei, Förderung der Symbiose&quot; nicht widersprechen. Jegliche Gesetze, Institutionen oder Kultivierungsmethoden, die dem Geist dieser Erklärung widersprechen, sind ungültig.</p><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Die Erklärung der Anker-Symbiotischen Zivilisation ist das erste Zivilisationsprogramm in der Geschichte von Heng Yuan Zhou, das die &quot;Symbiose&quot; zum Kern und das &quot;gemeinsame Fortschreiten der Zehntausend Rassen&quot; zum Ziel hat. Sie proklamiert das Ende einer alten Ära und den Beginn einer neuen. Unter der Anleitung der Erklärung wird Heng Yuan Zhou in die ultimative Richtung der Symbiose der Zehntausend Rassen und des Dimensionsaufstiegs des Kosmos voranschreiten.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Gesamtüberblick des Kosmos von Heng Yuan Zhou)</li><li>03-共生文明宪章 (Verfassung der Symbiotischen Zivilisation)</li><li>04-反掠夺主义核心论纲 (Kern-Thesen des Anti-Räuberismus)</li></ul>',20)])])}const m=n(s,[["render",d]]);export{c as __pageData,m as default};
